// Step 2: Validate & Sanitize Incoming Lead Data
const raw = $input.first().json.body || $input.first().json;

const name = (raw.name || '').toString().trim();
const email = (raw.email || '').toString().trim().toLowerCase();
const phone = (raw.phone || '').toString().trim();
const company = (raw.company || 'Not Provided').toString().trim();
const budget = (raw.budget || 'Not Specified').toString().trim();
const timeline = (raw.timeline || 'Not Specified').toString().trim();
const message = (raw.message || '').toString().trim();
const source = (raw.source || 'Direct Webhook').toString().trim();

const errors = [];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!name || name.length < 2) {
  errors.push("Missing or invalid 'name' (min 2 chars required).");
}
if (!email || !emailRegex.test(email)) {
  errors.push("Missing or invalid 'email' address.");
}
if (!message || message.length < 5) {
  errors.push("Missing or too short 'message' / inquiry details.");
}

const timestamp = new Date().toISOString();
const lead_id = 'LEAD-' + Math.floor(100000 + Math.random() * 900000);

return [
  {
    json: {
      lead_id,
      timestamp,
      name,
      email,
      phone: phone || 'N/A',
      company,
      budget,
      timeline,
      message,
      source,
      is_valid: errors.length === 0,
      validation_errors: errors.join(' | ')
    }
  }
];

// Step 5: Evaluate Duplicate Check Result
const leadData = $('2. Validate & Normalize Lead').first().json;
const sheetLookup = $input.first().json;

// If Google Sheets returned a matching row with an email, it's a duplicate
const isDuplicate = Boolean(sheetLookup && sheetLookup.email && sheetLookup.email.toLowerCase() === leadData.email.toLowerCase());

return [
  {
    json: {
      ...leadData,
      is_duplicate: isDuplicate,
      existing_lead_id: isDuplicate ? (sheetLookup.lead_id || 'EXISTING') : null,
      existing_classification: isDuplicate ? (sheetLookup.classification || 'N/A') : null
    }
  }
];

