// Step 8: Parse Gemini AI Response with Rule-Based Fallback (Resilience Pattern)
const lead = $('5. Evaluate Duplicate Status').first().json;
const aiResponse = $input.first().json;

let parsed = null;
let usedFallback = false;

try {
  const rawText = aiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    const cleaned = rawText.replace(/```json|```/gi, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (err) {
  usedFallback = true;
}

// Rule-based fallback if Gemini API quota/network fails
if (!parsed || !['Hot', 'Warm', 'Cold'].includes(parsed.classification)) {
  usedFallback = true;
  const combinedText = `${lead.budget} ${lead.timeline} ${lead.message}`.toLowerCase();
  let classification = 'Cold';
  let score = 25;

  if (combinedText.includes('immediate') || combinedText.includes('urgent') || combinedText.includes('demo') || combinedText.includes('25,000') || combinedText.includes('enterprise')) {
    classification = 'Hot';
    score = 88;
  } else if (combinedText.includes('quarter') || combinedText.includes('month') || combinedText.includes('5,000') || combinedText.includes('agency')) {
    classification = 'Warm';
    score = 62;
  }

  parsed = {
    classification,
    score,
    reasoning: `[Fallback Rule Classifier] Classified as ${classification} based on budget (${lead.budget}) and timeline (${lead.timeline}).`,
    recommended_action: classification === 'Hot' ? 'Immediate AE call within 15 mins' : (classification === 'Warm' ? 'Send product deck & schedule discovery' : 'Add to newsletter'),
    personalized_email_subject: `Thanks for reaching out to us, ${lead.name}!`,
    personalized_email_body: `Hi ${lead.name},\n\nThank you for contacting us regarding ${lead.company}. Our team has received your inquiry and will follow up shortly.\n\nBest regards,\nGrowth Automation Team`
  };
}

const statusMap = {
  Hot: 'Notified - Instant AE Alert',
  Warm: 'Notified - Nurture Sequence',
  Cold: 'Logged - Newsletter Only'
};

return [
  {
    json: {
      ...lead,
      classification: parsed.classification,
      score: parsed.score,
      ai_reasoning: parsed.reasoning,
      recommended_action: parsed.recommended_action,
      personalized_email_subject: parsed.personalized_email_subject,
      personalized_email_body: parsed.personalized_email_body,
      status: statusMap[parsed.classification] || 'Processed',
      used_ai_fallback: usedFallback
    }
  }
];

